"""Write the viewer's generated files: examples.js (the spec's example records, collections and
table spec, which the viewer opens with) and identifying.js (the fields the schemas mark
x-identifying, which a published table leaves out). Run after changing schema/:
python viewer/make_examples.py (tests/test_viewer.py checks both are current)."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXAMPLES = ROOT / "schema" / "examples"
FILES = [
    "paper.estrec-collection.json",
    "session.estrec-collection.json",
    "replication.estrec-collection.json",
    "replication.members.jsonl",
    "iv.estrec.json",
    "glm-logit.estrec.json",
    "dfeols-linear-fe.estrec.json",
    "paper.estrec-table.json",
]


def content() -> str:
    files = [{"name": n, "text": (EXAMPLES / n).read_text(encoding="utf-8")} for n in FILES]
    body = json.dumps(files, ensure_ascii=False, indent=0)
    return (
        "// Generated by viewer/make_examples.py from schema/examples/ (CC0). Don't edit.\n"
        f"window.EST_EXAMPLES = {body};\n"
    )


def identifying() -> list[str]:
    """Every x-identifying path in the core and the registered profiles, outside the sections
    the core digest covers (removing those would break the digest)."""
    import sys

    sys.path.insert(0, str(ROOT / "src"))
    from estimation_format import records as est

    sc = est.load_schemas()
    docs = sc.documents()
    paths = set(est.identifying_paths(sc.core, docs))
    for prof in sc.profiles.values():
        paths |= set(est.identifying_paths(prof, docs))
    return sorted(p for p in paths if p.replace("[*]", ".").split(".")[0] not in est.CORE)


def identifying_js() -> str:
    body = json.dumps(identifying(), indent=1)
    return (
        "// Generated by viewer/make_examples.py from the schemas' x-identifying marks (CC0). Don't edit.\n"
        "(function (root) {\n"
        f"  var paths = {body};\n"
        '  if (typeof module === "object" && module.exports) module.exports = paths;\n'
        "  else root.EST_IDENTIFYING = paths;\n"
        '})(typeof self !== "undefined" ? self : this);\n'
    )


if __name__ == "__main__":
    (ROOT / "viewer" / "examples.js").write_text(content(), encoding="utf-8")
    (ROOT / "viewer" / "identifying.js").write_text(identifying_js(), encoding="utf-8")
